TriageOutput predict_triage(const TriageInput* in) {
    TriageOutput out;
    double x[6];

    x[0] = ((double)in->age - 51.88655978) / 18.07698031;
    x[1] = (double)in->sex;
    x[2] = ((double)in->systolic_bp - 129.70154532) / 17.46670113;
    x[3] = ((double)in->heart_rate - 87.13741719) / 16.06338771;
    x[4] = ((double)in->respiratory_rate - 18.13620791) / 3.72983916;
    x[5] = ((double)in->spo2 - 95.96870524) / 2.72581817;

    double p[4];
    score_lgbm_multiclass(x, p);

    int best = 0;
    for (int k = 0; k < 4; ++k) {
        out.probs[k] = (float)p[k];
        if (p[k] > p[best]) {
            best = k;
        }
    }
    out.predicted_esi = best + 1;
    return out;
}
